import{z as E,x as A,o,c as p,q as n,j as i,D as a,d as r,s as c,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"torch.compile 与 Inductor","description":"","frontmatter":{"title":"torch.compile 与 Inductor","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/torch-compile-inductor.md","filePath":"llm/torch-compile-inductor.md","lastUpdated":1791063341000}'),m={name:"llm/torch-compile-inductor.md"};function s(h,e,B,u,D,P){const l=A("Mermaid");return o(),p("div",null,[e[2]||(e[2]=n('<h1 id="torch-compile-与-inductor" tabindex="-1">torch.compile 与 Inductor <a class="header-anchor" href="#torch-compile-与-inductor" aria-label="Permalink to &quot;torch.compile 与 Inductor&quot;">​</a></h1><div class="epigraph"><p>把动态 Python 字节码收成图，再由编译器后端生成融合核：训练和推理都可以少付一次次算子启动，而不必先把模型手写成 CUDA。</p><footer>—— Ansel et al., PyTorch 2: Faster Machine Learning Through Dynamic Python Bytecode Transformation and Graph Compilation, ASPLOS 2024</footer></div><p><a href="/llm/long-context-memory-curve">上一课</a>把会计收到三条曲线。本单元换成「引擎里的细节」：公式允许的屋顶，还要核与编译器去贴近。PyTorch 2 的 <code>torch.compile</code> 用 TorchDynamo 抓图、AOTAutograd 拆正反向、Inductor 降到 OpenAI Triton 或 C++/CUDA。服务引擎常常 <em>不用</em> 这条路径（vLLM 手写注意力），但自定义层、采样前后处理、以及尚未手写的 MLP 仍走编译器。本课写它能融什么、decode 上为什么经常融不动注意力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>eager 模式每步是一串小核：RMSNorm、SiLU、残差加。decode 已在带宽墙，核启动与中间张量写回 HBM 会把有效带宽再削一截。手写融合核质量高、覆盖窄。缺口是自动融合：在动态形状（连续批变长、分页 KV）下仍能抓到图。Dynamo 靠字节码分析，遇到数据依赖的 Python 控制流会 graph break，融合在断裂处停止——LLM 服务里最常见的断裂是：采样、分页译址、以及 <code>if</code> 出来的投机接受。</p><p><span class="marginnote"><code>reduce-overhead</code> / <code>max-autotune</code> 模式改的是 CUDA Graph 与选择策略，不是另一套注意力算法。编译不改变 <a href="/llm/flashattention">SDPA</a> 的数学；没有对应模板时 Inductor 会生成比 FA 慢的通用核。</span></p><p><span class="marginnote">「graph break」就是编译器在读你的 Python 代码时，遇到一段它看不懂的控制流——比如依赖运行期数据的 <code>if</code>、随机采样、分页查表——只好在这里停笔，把计算图切成两截，中间那段退回 Python 逐条解释执行。图一断，跨断点的融合优化自然就做不成了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对静态或半静态部分（固定 \\(B\\)、固定 \\(n\\) 的 MLP、Norm）<code>compile</code> 收益最大；注意力应显式走 FA / FlashInfer，而不是指望 Inductor 写出同等 IO 感知核。CUDA Graph 要求形状稳定：连续批的 \\(B\\) 与 \\(n\\) 每拍都变，整模型一张图会频繁重录。实践是「静态子图 + 动态注意力核」拼起来，或对 bucket 形状各录一张图。首次编译延迟打在冷启动，服务要预热。</p><p>动态形状用 <code>mark_dynamic</code>；过度动态会让 Inductor 放弃融合或反复编译。与<a href="/llm/sampler-kernel">采样器内核</a>的关系：采样含 RNG 与不规则参数，通常留在手写核，不要 compile 进同一张图后还 graph break 在 <code>multinomial</code>。</p><p><span class="marginnote">可以把它想象成录像：CUDA Graph 把一整套核启动指令「录」成一盘带子，之后每步整盘重放，省去逐个发射指令的 CPU 开销。但形状一变就得重录——所以工程上按 batch 和序列长度分成几个「桶」，每个桶各录一盘，请求落进哪个桶就放哪盘带子。</span></p>',11)),(o(),i(d,null,{default:a(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PY%5B%22eager%20Python%22%5D%20--%3E%20DY%5B%22Dynamo%20%E6%8A%93%E5%9B%BE%22%5D%0A%20%20DY%20--%3E%20AOT%5B%22AOTAutograd%22%5D%0A%20%20AOT%20--%3E%20IND%5B%22Inductor%22%5D%0A%20%20IND%20--%3E%20TR%5B%22Triton%20%2F%20CUDA%22%5D%0A%20%20DY%20--%3E%20BR%5B%22graph%20break%3A%20%E9%87%87%E6%A0%B7%20%2F%20%E5%88%86%E9%A1%B5%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"融合提高算术强度：中间激活留在寄存器或 SRAM，少写 HBM，正好补 decode 的强度缺口。但注意力的 IO 感知算法有专门的在线 softmax 结构，通用编译器短时间追不上 FA 论文里的手工分块。因此「整模型 compile」在 LLM decode 上的真实收益往往来自 MLP/Norm，注意力加速来自插件。CUDA Graph 减 CPU 发射延迟，在小核很多时显著；大 FA 核主导时收益变薄。",-1)),(o(),i(d,null,{default:a(()=>[c(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E7%9B%B8%E9%82%BB%E7%9A%84%20Norm%20%2F%20SiLU%20%2F%20%E6%AE%8B%E5%B7%AE%E5%8A%A0%22%5D%20--%3E%20Q%7B%22%E8%9E%8D%E5%90%88%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22eager%EF%BC%9A%E9%80%90%E6%A0%B8%E5%90%AF%E5%8A%A8%22%7C%20HBM%5B%22%E6%AF%8F%E4%B8%AA%E6%A0%B8%E7%9A%84%E8%BE%93%E5%87%BA%E9%83%BD%E5%86%99%E5%9B%9E%20HBM%20%E5%86%8D%E8%AF%BB%E5%87%BA%22%5D%0A%20%20HBM%20--%3E%20COST%5B%22%E4%B8%AD%E9%97%B4%E5%BE%80%E8%BF%94%E6%8A%8A%E6%9C%89%E6%95%88%E5%B8%A6%E5%AE%BD%E5%86%8D%E5%89%8A%E4%B8%80%E6%88%AA%22%5D%0A%20%20Q%20--%3E%7C%22Inductor%20%E8%9E%8D%E5%90%88%22%7C%20REG%5B%22%E4%B8%AD%E9%97%B4%E5%80%BC%E7%95%99%E5%9C%A8%E5%AF%84%E5%AD%98%E5%99%A8%E6%88%96%20SRAM%22%5D%0A%20%20REG%20--%3E%20GAIN%5B%22%E7%9C%81%E6%8E%89%20HBM%20%E5%BE%80%E8%BF%94%EF%BC%8C%E8%B4%B4%E8%BF%91%E5%B8%A6%E5%AE%BD%E5%B1%8B%E9%A1%B6%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在分页 KV 上强迫整图静态。不要把 compile 的加速比（相对 eager 朴素 SDPA）拿去和已经接好 FA 的引擎比。数值：编译可能改运算顺序，半精度下尾差要验收。下一课：即使编译了，块大小仍要自动调。</p><p>出处：Ansel et al., ASPLOS 2024。Triton 见 Tillet et al., MAPL 2019。</p><p><span class="marginnote">常见误区：拿 <code>torch.compile</code> 对「没接 FA 的 eager 朴素注意力」测出的 2 倍加速，去宣传「编译让服务快 2 倍」。基准里的注意力本来就慢；正确对照是已接好 FA 的引擎，真实收益通常只剩 MLP / Norm 融合那一部分，数字要分开报。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>torch.compile</code> 抓图并融合；LLM decode 的注意力通常仍走手写 FA。</li><li>graph break 出在采样、分页、投机控制流。</li><li>CUDA Graph 要形状桶；连续批不能一张图打天下。</li><li>收益主要是少写中间激活与少启动，贴近带宽屋顶。</li><li>冷编译要预热，计入 TTFT 或启动 SLA。</li><li>下一课：核参数自动搜索。</li><li>出处：Ansel et al., ASPLOS 2024。</li></ul>',6))])}const f=E(m,[["render",s]]);export{C as __pageData,f as default};
